-- MP-0013: guarded editorial content import. Deploy portraits before applying.

begin;

do $$ begin
 if not exists(select 1 from public.entities where slug='pas' and type='party') then raise exception 'MP-0013: missing or wrong parent'; end if;
 if not exists(select 1 from public.entities where slug='perikatan-nasional' and type='alliance') then raise exception 'MP-0013: missing or wrong parent'; end if;
 if exists(select 1 from public.entities where slug in ('abdul-hadi-awang','rosol-wahid','wan-hassan-mohd-ramli') and (type <> 'politician' or owner_id is not null)) then raise exception 'MP-0013: ownership or type conflict'; end if;
 if exists(select 1 from public.entities where type='politician' and lower(constituency) in ('marang','hulu terengganu','dungun') and slug not in ('abdul-hadi-awang','rosol-wahid','wan-hassan-mohd-ramli')) then raise exception 'MP-0013: constituency identity conflict'; end if;
 if exists(select 1 from public.milestones m join public.entities e on e.id=m.entity_id where m.import_key like 'MP-0013:%' and (m.source_type <> 'editorial' or e.slug not in ('abdul-hadi-awang','rosol-wahid','wan-hassan-mohd-ramli') or m.import_key not like 'MP-0013:' || e.slug || ':%')) then raise exception 'MP-0013: milestone identity conflict'; end if;
end $$;

insert into public.entities (type,parent_id,slug,name,bloc,position,constituency,state,description,website,photo_path,photo_source_url,photo_credit,profile_checked_at,profile_sources) select 'politician',parent.id,'abdul-hadi-awang','Abdul Hadi Awang','opposition','President of PAS; Member of the Dewan Rakyat','Marang','Terengganu','Abdul Hadi Awang represents Marang, Terengganu, in the Dewan Rakyat. Current role: President of PAS; Member of the Dewan Rakyat. A PAS member.','https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4076','/portraits/abdul-hadi-awang.webp','https://www.parlimen.gov.my/images/webuser/ahli/2022/P037.png','Parliament of Malaysia','2026-11-09','[{"label": "Parliament · official profile", "url": "https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4076"}, {"label": "PAS · current parliamentary representatives", "url": "https://pas.org.my/ahli-parlimen-pas-pru-ke-15/"}]'::jsonb from public.entities parent where parent.slug='pas' on conflict (slug) do update set parent_id=excluded.parent_id,name=excluded.name,bloc=excluded.bloc,position=excluded.position,constituency=excluded.constituency,state=excluded.state,description=excluded.description,website=excluded.website,photo_path=excluded.photo_path,photo_source_url=excluded.photo_source_url,photo_credit=excluded.photo_credit,profile_checked_at=excluded.profile_checked_at,profile_sources=excluded.profile_sources where public.entities.type='politician' and public.entities.owner_id is null and ROW(public.entities.parent_id,public.entities.name,public.entities.bloc,public.entities.position,public.entities.constituency,public.entities.state,public.entities.description,public.entities.website,public.entities.photo_path,public.entities.photo_source_url,public.entities.photo_credit,public.entities.profile_checked_at,public.entities.profile_sources) IS DISTINCT FROM ROW(excluded.parent_id,excluded.name,excluded.bloc,excluded.position,excluded.constituency,excluded.state,excluded.description,excluded.website,excluded.photo_path,excluded.photo_source_url,excluded.photo_credit,excluded.profile_checked_at,excluded.profile_sources);

insert into public.entities (type,parent_id,slug,name,bloc,position,constituency,state,description,website,photo_path,photo_source_url,photo_credit,profile_checked_at,profile_sources) select 'politician',parent.id,'rosol-wahid','Rosol Wahid','opposition','Member of the Dewan Rakyat','Hulu Terengganu','Terengganu','Rosol Wahid represents Hulu Terengganu, Terengganu, in the Dewan Rakyat. Parliament lists affiliation with Perikatan Nasional (PN).','https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4077','/portraits/rosol-wahid.webp','https://www.parlimen.gov.my/images/webuser/ahli/2022/P038.png','Parliament of Malaysia','2026-11-09','[{"label": "Parliament · official profile", "url": "https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4077"}, {"label": "Parliament · current Dewan Rakyat directory", "url": "https://www.parlimen.gov.my/ahli-dewan.html?uweb=dr"}]'::jsonb from public.entities parent where parent.slug='perikatan-nasional' on conflict (slug) do update set parent_id=excluded.parent_id,name=excluded.name,bloc=excluded.bloc,position=excluded.position,constituency=excluded.constituency,state=excluded.state,description=excluded.description,website=excluded.website,photo_path=excluded.photo_path,photo_source_url=excluded.photo_source_url,photo_credit=excluded.photo_credit,profile_checked_at=excluded.profile_checked_at,profile_sources=excluded.profile_sources where public.entities.type='politician' and public.entities.owner_id is null and ROW(public.entities.parent_id,public.entities.name,public.entities.bloc,public.entities.position,public.entities.constituency,public.entities.state,public.entities.description,public.entities.website,public.entities.photo_path,public.entities.photo_source_url,public.entities.photo_credit,public.entities.profile_checked_at,public.entities.profile_sources) IS DISTINCT FROM ROW(excluded.parent_id,excluded.name,excluded.bloc,excluded.position,excluded.constituency,excluded.state,excluded.description,excluded.website,excluded.photo_path,excluded.photo_source_url,excluded.photo_credit,excluded.profile_checked_at,excluded.profile_sources);

insert into public.entities (type,parent_id,slug,name,bloc,position,constituency,state,description,website,photo_path,photo_source_url,photo_credit,profile_checked_at,profile_sources) select 'politician',parent.id,'wan-hassan-mohd-ramli','Wan Hassan Mohd Ramli','opposition','Member of the Dewan Rakyat','Dungun','Terengganu','Wan Hassan Mohd Ramli represents Dungun, Terengganu, in the Dewan Rakyat. A PAS member.','https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4078','/portraits/wan-hassan-mohd-ramli.webp','https://www.parlimen.gov.my/images/webuser/ahli/2022/P039.jpg','Parliament of Malaysia','2026-11-09','[{"label": "Parliament · official profile", "url": "https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4078"}, {"label": "PAS · current parliamentary representatives", "url": "https://pas.org.my/ahli-parlimen-pas-pru-ke-15/"}]'::jsonb from public.entities parent where parent.slug='pas' on conflict (slug) do update set parent_id=excluded.parent_id,name=excluded.name,bloc=excluded.bloc,position=excluded.position,constituency=excluded.constituency,state=excluded.state,description=excluded.description,website=excluded.website,photo_path=excluded.photo_path,photo_source_url=excluded.photo_source_url,photo_credit=excluded.photo_credit,profile_checked_at=excluded.profile_checked_at,profile_sources=excluded.profile_sources where public.entities.type='politician' and public.entities.owner_id is null and ROW(public.entities.parent_id,public.entities.name,public.entities.bloc,public.entities.position,public.entities.constituency,public.entities.state,public.entities.description,public.entities.website,public.entities.photo_path,public.entities.photo_source_url,public.entities.photo_credit,public.entities.profile_checked_at,public.entities.profile_sources) IS DISTINCT FROM ROW(excluded.parent_id,excluded.name,excluded.bloc,excluded.position,excluded.constituency,excluded.state,excluded.description,excluded.website,excluded.photo_path,excluded.photo_source_url,excluded.photo_credit,excluded.profile_checked_at,excluded.profile_sources);

do $$ begin if (select count(*) from public.entities where slug in ('abdul-hadi-awang','rosol-wahid','wan-hassan-mohd-ramli') and type='politician' and owner_id is null) <> 3 then raise exception 'MP-0013: concurrent ownership or identity change'; end if; end $$;

insert into public.milestones (entity_id,import_key,title,category,status,progress,target_date,promise_date,promise_url,evidence_date,evidence_url,description,progress_note,progress_checked_at,source_type,is_sample) select e.id,'MP-0013:wan-hassan-mohd-ramli:subsidised-basic-goods','Run subsidised basic-goods sales for Dungun residents','Social welfare','in_progress',null,null,null,null,'2025-03-10','https://www.sinarharian.com.my/article/716777/berita/wawancara/anjur-jualan-murah-tangani-kos-sara-hidup-rakyat','Wan Hassan described service-centre cheap-sales programmes and cooperation with the state’s Pasar Berkat.','The interview records the service centre covering part of goods costs. This is a March 2025 activity snapshot, not an audited cost-of-living impact result. Later programme coverage and completion remain unverified.','2026-11-09','editorial',false from public.entities e where e.slug='wan-hassan-mohd-ramli' on conflict (import_key) do update set title=excluded.title,category=excluded.category,status=excluded.status,progress=excluded.progress,target_date=excluded.target_date,promise_date=excluded.promise_date,promise_url=excluded.promise_url,evidence_date=excluded.evidence_date,evidence_url=excluded.evidence_url,description=excluded.description,progress_note=excluded.progress_note,progress_checked_at=excluded.progress_checked_at,source_type=excluded.source_type,is_sample=excluded.is_sample where public.milestones.entity_id=excluded.entity_id and public.milestones.source_type='editorial' and ROW(public.milestones.title,public.milestones.category,public.milestones.status,public.milestones.progress,public.milestones.target_date,public.milestones.promise_date,public.milestones.promise_url,public.milestones.evidence_date,public.milestones.evidence_url,public.milestones.description,public.milestones.progress_note,public.milestones.progress_checked_at,public.milestones.source_type,public.milestones.is_sample) IS DISTINCT FROM ROW(excluded.title,excluded.category,excluded.status,excluded.progress,excluded.target_date,excluded.promise_date,excluded.promise_url,excluded.evidence_date,excluded.evidence_url,excluded.description,excluded.progress_note,excluded.progress_checked_at,excluded.source_type,excluded.is_sample);

